"""The Broken Campus lab must contain exactly the faults its answer key claims.

The dangerous failure for a scored practice lab is not "generation crashed" — it
is "generation succeeded and the fault silently did not land". Then the student
gets a lab where the answer key names a defect that is not there, and no amount
of correct analysis can earn the points.

These tests are written against that failure. They treat the answer key as a
*claim* and prove the claim against the generated bytes.
"""

from __future__ import annotations

import pytest

from trident.labgen import available, build_configs, generate
from trident.labgen.broken_campus import TOPOLOGY
from trident.labgen.faults import (
    FaultApplicationError,
    faulted_configs,
    intended_configs,
)
from trident.labgen.spec import (
    DeviceRole,
    DeviceSpec,
    FaultCategory,
    FaultSpec,
    InterfaceSpec,
    LinkSpec,
    Severity,
    TargetKind,
    TopologySpec,
)

# ---------------------------------------------------------------------------
# Spec shape
# ---------------------------------------------------------------------------


def test_broken_campus_spec_is_well_formed() -> None:
    assert TOPOLOGY.validate() == []


def test_broken_campus_has_at_least_twelve_faults() -> None:
    assert len(TOPOLOGY.faults) >= 12


def test_broken_campus_scores_to_one_hundred() -> None:
    assert TOPOLOGY.point_total() == 100


def test_broken_campus_covers_the_required_categories() -> None:
    kinds = {f.category for f in TOPOLOGY.faults}
    required = {
        FaultCategory.ADDRESSING,
        FaultCategory.VLAN,
        FaultCategory.TRUNK,
        FaultCategory.ROUTING,
        FaultCategory.GATEWAY,
        FaultCategory.DHCP,
        FaultCategory.INTERFACE,
        FaultCategory.SECURITY,
    }
    missing = {k for k in required if k not in kinds}
    assert not missing, f"categories missing from the lab: {missing}"


def test_broken_campus_repeats_at_least_two_categories() -> None:
    """A lab where every category appears once is a checklist, not a diagnosis."""
    repeats = [cat for cat, faults in TOPOLOGY.by_category().items() if len(faults) > 1]
    assert len(repeats) >= 3


def test_every_device_is_cabled() -> None:
    linked = {link.a for link in TOPOLOGY.links} | {link.b for link in TOPOLOGY.links}
    unlinked = {d.name for d in TOPOLOGY.devices} - linked
    assert not unlinked, f"devices with no cable: {unlinked}"


def test_no_port_is_used_twice() -> None:
    ports = [(l.a, l.a_port) for l in TOPOLOGY.links] + [(l.b, l.b_port) for l in TOPOLOGY.links]
    duplicates = {p for p in ports if ports.count(p) > 1}
    assert not duplicates, f"ports cabled twice: {duplicates}"


def test_required_hardware_is_present() -> None:
    """The brief's equipment, plus the ISP peer R1's default route points at.

    The ISP router is not decoration: without a live neighbour on Gi0/1, R1's
    ``ip route`` line is rejected by IOS and the routing fault disappears.
    """
    roles = [d.role for d in TOPOLOGY.devices]
    assert roles.count(DeviceRole.ROUTER) == 2  # R1 + the ISP peer
    assert roles.count(DeviceRole.SWITCH) == 2
    assert roles.count(DeviceRole.PC) == 6
    assert roles.count(DeviceRole.SERVER) == 1


def test_every_fault_has_progressive_hints() -> None:
    for fault in TOPOLOGY.faults:
        assert fault.hint_1, fault.fault_id
        assert fault.hint_2, fault.fault_id
        assert fault.hint_1 != fault.hint_2, fault.fault_id
        assert fault.points > 0, fault.fault_id


def test_fault_ids_are_unique_and_descriptive() -> None:
    ids = [f.fault_id for f in TOPOLOGY.faults]
    assert len(ids) == len(set(ids))
    for fault_id in ids:
        assert "-" in fault_id, f"{fault_id} is not descriptive"


# ---------------------------------------------------------------------------
# Fault application: the answer key must match the bytes
# ---------------------------------------------------------------------------


def test_the_reference_build_has_none_of_the_faults() -> None:
    """No fault's ``actual`` value may appear at the place that fault edits.

    Scoped deliberately: `` name STUDENTS`` is a correct line inside VLAN 20's
    block, so an unscoped search would call the VLAN 30 naming fault a no-op.
    The claim a fault makes is local — "this line, in this block, on this
    device" — and so is this check.
    """
    from trident.labgen.faults import _block_bounds

    intended = intended_configs(TOPOLOGY)
    for fault in TOPOLOGY.faults:
        if fault.target is TargetKind.ENDHOST:
            continue
        if fault.actual.strip().startswith("!"):
            continue  # a removal has no positive value to search for
        actual = fault.actual.strip()
        if not actual:
            continue
        lines = intended[fault.device]
        if fault.target is TargetKind.INTERFACE_LINE:
            bounds = _block_bounds(lines, f"interface {fault.interface}")
            assert bounds is not None, (fault.fault_id, "interface missing")
            window = lines[bounds[0]:bounds[1]]
        elif fault.target is TargetKind.CONTEXT_LINE:
            bounds = _block_bounds(lines, fault.context or "")
            assert bounds is not None, (fault.fault_id, "context missing")
            window = lines[bounds[0]:bounds[1]]
        else:
            window = lines
        assert actual not in [line.strip() for line in window], (
            f"fault {fault.fault_id}: {actual!r} is already present in the "
            f"intended config of {fault.device}"
        )


def test_every_fault_changes_at_least_one_line() -> None:
    """A config fault that edits nothing is not a fault.

    Scoped to faults whose whole effect *is* a config line. An ENDHOST fault
    changes a NIC field and a VLAN_DB fault changes the VLAN database; asserting
    that those edit running-config would be asserting something false. Their
    observable effects are covered by ``test_labgen_live.py``.
    """
    intended = intended_configs(TOPOLOGY)
    faulted, applied = faulted_configs(TOPOLOGY)
    text_targets = {TargetKind.INTERFACE_LINE, TargetKind.CONTEXT_LINE, TargetKind.GLOBAL_LINE, TargetKind.BLOCK}
    for change in applied:
        fault = next(f for f in TOPOLOGY.faults if f.fault_id == change.fault_id)
        if fault.target not in text_targets:
            continue
        assert change.removed or change.added, (
            f"fault {change.fault_id} removed and added nothing"
        )
    changed_devices = {d for d in intended if intended[d] != faulted[d]}
    # ENDHOST and VLAN_DB faults live outside the config text by design: the NIC
    # and the VLAN database are where those facts actually are.
    device_level = {
        f.device
        for f in TOPOLOGY.faults
        if f.target not in {TargetKind.ENDHOST, TargetKind.VLAN_DB}
    }
    assert device_level <= changed_devices, (
        f"faults on {sorted(device_level - changed_devices)} did not change config"
    )


def test_no_orphaned_block_body() -> None:
    """Removing a block must remove its body too.

    The first implementation deleted ``vlan 10`` and left `` name ADMIN`` sitting
    in global config — invalid IOS that the simulator would reject, on a device
    whose fault description says nothing about it.
    """
    faulted, _ = faulted_configs(TOPOLOGY)
    for dev, lines in faulted.items():
        for line in lines:
            stripped = line.strip()
            if stripped.startswith("name ") and line == line.lstrip():
                pytest.fail(f"{dev} has an orphaned VLAN name at global level: {line!r}")


def test_a_fault_for_a_missing_line_is_refused_not_ignored() -> None:
    """If the spec and the fault disagree, generation must stop."""
    dev = DeviceSpec(
        name="SW1",
        model="2960-24TT",
        role=DeviceRole.SWITCH,
        x=0,
        y=0,
        interfaces=(InterfaceSpec(name="Fa0/1", lines=("switchport mode access",)),),
    )
    fault = FaultSpec(
        fault_id="x-not-there",
        category=FaultCategory.VLAN,
        severity=Severity.MINOR,
        device="SW1",
        interface="Fa0/1",
        description="replace a line that does not exist",
        expected="switchport access vlan 10",
        actual="switchport access vlan 20",
        symptom="none",
        points=1,
        hint_1="h",
        hint_2="h2",
    )
    spec = TopologySpec(name="t", title="t", devices=[dev], links=[], faults=[fault])
    with pytest.raises(FaultApplicationError, match="no line"):
        faulted_configs(spec)


def test_a_fault_pointing_at_a_missing_interface_is_refused() -> None:
    dev = DeviceSpec(
        name="SW1", model="2960-24TT", role=DeviceRole.SWITCH, x=0, y=0,
    )
    fault = FaultSpec(
        fault_id="x-ghost-iface",
        category=FaultCategory.INTERFACE,
        severity=Severity.MINOR,
        device="SW1",
        interface="Fa0/9",
        description="no such interface",
        expected="no shutdown",
        actual="shutdown",
        symptom="none",
        points=1,
        hint_1="h",
        hint_2="h2",
    )
    spec = TopologySpec(name="t", title="t", devices=[dev], links=[], faults=[fault])
    with pytest.raises(FaultApplicationError, match="no 'interface Fa0/9' block"):
        faulted_configs(spec)


def test_spec_validation_catches_a_points_total_that_is_not_100() -> None:
    fault = FaultSpec(
        fault_id="a", category=FaultCategory.VLAN, severity=Severity.MINOR,
        device="SW1", interface=None, description="d", expected="x", actual="y",
        symptom="s", points=50, hint_1="h", hint_2="h2",
    )
    dev = DeviceSpec(name="SW1", model="2960-24TT", role=DeviceRole.SWITCH, x=0, y=0)
    spec = TopologySpec(name="t", title="t", devices=[dev], links=[], faults=[fault])
    problems = spec.validate()
    assert any("expected 100" in p for p in problems)


def test_spec_validation_catches_a_link_to_a_missing_device() -> None:
    dev = DeviceSpec(name="SW1", model="2960-24TT", role=DeviceRole.SWITCH, x=0, y=0)
    spec = TopologySpec(
        name="t", title="t", devices=[dev],
        links=[LinkSpec("SW1", "Fa0/1", "GHOST", "Fa0/1")],
    )
    problems = spec.validate()
    assert any("unknown device 'GHOST'" in p for p in problems)


# ---------------------------------------------------------------------------
# Real .pkt generation
# ---------------------------------------------------------------------------

_available, _why = available()


@pytest.mark.skipif(not _available, reason=_why)
def test_generate_writes_a_decodable_pkt(tmp_path) -> None:
    result = generate(TOPOLOGY, tmp_path / "broken_campus.pkt", apply_faults=True)
    assert result.encode_ok, result.notes
    assert result.path.is_file()
    assert result.path.stat().st_size > 5000
    assert result.device_count == len(TOPOLOGY.devices)
    assert result.link_count == len(TOPOLOGY.links)
    # Encoding is not compatibility, and the result must not claim it is.
    assert result.verified is False
    assert "Packet Tracer" in result.verification_note


@pytest.mark.skipif(not _available, reason=_why)
def test_student_and_reference_builds_differ(tmp_path) -> None:
    student = generate(TOPOLOGY, tmp_path / "s.pkt", apply_faults=True)
    reference = generate(TOPOLOGY, tmp_path / "r.pkt", apply_faults=False)
    assert student.sha256 != reference.sha256
    assert student.encode_ok and reference.encode_ok


@pytest.mark.skipif(not _available, reason=_why)
def test_generated_pkt_decodes_to_the_same_device_names(tmp_path) -> None:
    from pkt_core.codec.container import decode
    from pkt_core.models import Lab

    result = generate(TOPOLOGY, tmp_path / "l.pkt", apply_faults=True)
    lab = Lab.from_bytes(decode(str(result.path)).xml)
    assert {d.name for d in lab.devices} == {d.name for d in TOPOLOGY.devices}


@pytest.mark.skipif(not _available, reason=_why)
def test_the_faulted_config_is_what_lands_in_the_file(tmp_path) -> None:
    """The answer key describes the file, not a parallel in-memory idea of it."""
    from pkt_core.codec.container import decode
    from pkt_core.models import Lab

    result = generate(TOPOLOGY, tmp_path / "l.pkt", apply_faults=True)
    lab = Lab.from_bytes(decode(str(result.path)).xml)
    # The generated XML stores the config as <RUNNINGCONFIG><LINE>…; read it back
    # through the same decode rather than trusting `result.configs`. Each
    # assertion is scoped to the fault's own device: "vlan 10" is a legitimate
    # block on SW-ACCESS while being the deleted block on SW-DIST, so a
    # whole-file search would prove nothing.
    import re

    text = decode(str(result.path)).xml.decode("utf-8", "replace")
    blocks: dict[str, str] = {}
    for chunk in re.findall(r"<DEVICE>.*?</DEVICE>", text, re.DOTALL):
        name = re.search(r"<NAME[^>]*>(.*?)</NAME>", chunk, re.DOTALL)
        if name:
            blocks[name.group(1).strip()] = chunk
    for fault in TOPOLOGY.faults:
        if fault.target is TargetKind.ENDHOST:
            continue
        if fault.actual.strip().startswith("!"):
            # A "remove this line" fault proves itself by the *expected* line
            # being gone. Matched as a whole ``<LINE>`` element, because
            # "vlan 10" is a substring of "switchport access vlan 10" and a
            # plain containment check would be meaningless.
            needle = f"<LINE>{fault.expected.strip()}</LINE>"
            assert needle not in blocks[fault.device], (
                f"fault {fault.fault_id}: {fault.expected!r} should have been "
                f"removed from {fault.device}"
            )
            continue
        actual = fault.actual.strip()
        if not actual:
            continue
        assert actual in blocks[fault.device], (
            f"fault {fault.fault_id}: {actual!r} is not in {fault.device}"
        )
    assert len(lab.devices) == len(TOPOLOGY.devices)


def test_available_reports_a_reason_either_way() -> None:
    ok, reason = available()
    assert isinstance(ok, bool)
    assert reason


# ---------------------------------------------------------------------------
# Answer-key separation
# ---------------------------------------------------------------------------


def test_build_configs_returns_the_faulted_network_by_default() -> None:
    default = build_configs(TOPOLOGY)
    explicit = build_configs(TOPOLOGY, apply_faults=True)
    assert default == explicit


def test_the_intended_build_differs_from_the_student_build() -> None:
    intended = build_configs(TOPOLOGY, apply_faults=False)
    student = build_configs(TOPOLOGY, apply_faults=True)
    differing = {d for d in intended if intended[d] != student[d]}
    assert differing, "no device differs between intended and student builds"
